SELECT DISTINCTROW Richieste.[Numero Record], Richieste.Oli, [Chimiche-Barriera].Oli, Richieste.[Anno Archivio], Richieste.[Data richiesta], Richieste.[Data Risposta], Richieste.[Data Ritardo], Richieste.Ritardo, Richieste.Richiedente, Richieste.Produttore, Richieste.Prodotto, Richieste.Cliente, Richieste.Descrizione, Richieste.[Motivo Richiesta], [Chimiche-Barriera].[Natura Chimica], [Chimiche-Barriera].Inerti, [Chimiche-Barriera].[Numero K], [Chimiche-Barriera].VCM, [Chimiche-Barriera].Stabilizzazione, [Chimiche-Barriera].[Delta Colore], [Chimiche-Barriera].PermeabilitàA, [Chimiche-Barriera].PermeabilitàB, [Chimiche-Barriera].Altro1, [Chimiche-Barriera].Altro2, [Chimiche-Barriera].Altro3, [Chimiche-Barriera].Altro4
FROM Richieste INNER JOIN [Chimiche-Barriera] ON Richieste.Oli = [Chimiche-Barriera].Oli
WHERE ((Richieste.Oli=[Schede]![SRichieste]![Oli]));
